def cached(fn):
    memo = {}
    def wrapper(x):
        if x not in memo:
            memo[x] = fn(x)
        return memo[x]
    return wrapper

@cached
def slow_square(x):
    print('compute')
    return x * x

print(slow_square(3)); print(slow_square(3))

import random, time

def flaky():
    if random.random() < 0.7:
        raise RuntimeError('boom')
    return 'ok'

for i in range(5):
    try:
        print(flaky())
        break
    except Exception as e:
        print('retry', i+1)
        time.sleep(0.05)

import functools

def log(fn):
    @functools.wraps(fn)
    def wrapper(*a, **k):
        print('calling', fn.__name__)
        return fn(*a, **k)
    return wrapper

@log
def greet(n):
    return f'hi {n}'

print(greet('Jon'))
